name: Social Copy Generator
on:
  pull_request:
    types: [opened, synchronize]
  issue_comment:
    types: [created, edited]

jobs:
  handle-pr-comment:
    if: github.event_name == 'issue_comment' && github.event.comment.in_reply_to_id == null
    runs-on: ubuntu-latest
    steps:
      - name: Check for social copy command
        id: check_command
        run: |
          COMMENT_BODY="${{ github.event.comment.body }}"
          if [[ "$COMMENT_BODY" == *"social copy"* ]]; then
            echo "command_found=true" >> $GITHUB_OUTPUT
            echo "pr_number=${{ github.event.issue.number }}" >> $GITHUB_OUTPUT
          fi

      - name: Generate social copy
        if: steps.check_command.outputs.command_found == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { exec } = require('child_process');
            const fs = require('fs');

            // Get PR diff
            const prNumber = ${{ steps.check_command.outputs.pr_number }};
            const diff = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            // Create prompt for Claude
            const prompt = `Analyze this PR diff and generate social media content:

            PR Title: ${diff.data.title}
            PR Description: ${diff.data.body || ''}
            Diff:
            ${diff.data.diff_url}

            Generate content for:
            1. Twitter/X post (280 characters max)
            2. LinkedIn post (500 characters max) 
            3. Blog post title and excerpt (150 characters max each)

            Format as markdown with clear sections.`;

            // Call Claude API (this would be your actual Claude integration)
            // For now, we'll simulate with placeholder content
            const response = {
              twitter: "Excited to share our latest update! We've enhanced our platform with new features that make development faster and more intuitive. #DeveloperTools #Innovation",
              linkedin: "We're thrilled to announce exciting improvements to our platform! Our latest update brings enhanced functionality and streamlined workflows that will boost your productivity. Check out what's new!",
              blog_title: "Enhancing Developer Productivity with New Platform Features",
              blog_excerpt: "Discover how our latest platform enhancements streamline development workflows and boost productivity for developers."
            };

            // Update comment with results
            const commentBody = `
### 📣 Generated Social Media Copies

#### Twitter/X
${response.twitter}

#### LinkedIn
${response.linkedin}

#### Blog Post
**Title:** ${response.blog_title}
**Excerpt:** ${response.blog_excerpt}

---
*This content was automatically generated. Check the [workflow logs](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}) for details.*
`;

            await github.rest.issues.updateComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: ${{ github.event.comment.id }},
              body: commentBody
            });

  generate-social-copy:
    if: github.event_name == 'pull_request' && github.event.action == 'opened'
    runs-on: ubuntu-latest
    steps:
      - name: Add social copy comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const commentBody = `
### 📣 Generate Social Media Copies

Check the box below to have Claude analyze this PR and generate social media content for Twitter/X, LinkedIn, and a blog post:

- [ ] Generate social media copies

After generation, you can use the "Regenerate" option to update content when changes are pushed.
`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: commentBody
            });
```

